-- ============================================================================
-- database/seeds/standard_departments.sql
--
-- 标准部门树 seed（23 个部门，12 顶级 + 11 二级子部门）
--
-- 命名规范：
--   name     = 中文（项目默认语言，前端默认显示）
--   name_en  = 英文（多语言对照，英文模式下显示）
--   code     = 部门编码（英文缩写，稳定不变）
--
-- 用法：
--   psql -U topems_prod -d topems_prod -f database/seeds/standard_departments.sql
--
-- 幂等：重复执行会因主键冲突报错，如需重置先 TRUNCATE hrm.departments CASCADE;
-- ============================================================================

-- ── 顶级部门（12 个）──

-- ── 二级子部门（11 个）──

-- 验证
SELECT count(*) AS total_departments FROM hrm.departments WHERE deleted_at IS NULL;
